import { defineConfig } from 'vite'
import vue from '@vitejs/plugin-vue'
import { viteSingleFile } from 'vite-plugin-singlefile'
import path from 'node:path'

const slug = process.env.H5_APP_SLUG || 'tintoo'
const entry = process.env.H5_SITE_ENTRY || 'tslow_entry.htm'
const flatEntry = entry.includes('/') ? false : !entry.startsWith('index')

export default defineConfig({
  plugins: [vue(), viteSingleFile()],
  resolve: {
    alias: {
      '@': path.resolve(__dirname, 'src'),
    },
  },
  server: {
    host: true,
    port: 5174,
  },
  build: {
    // Prefer flat prefix entry when register uses h5_site/{prefix}_entry.htm
    outDir: path.resolve(
      __dirname,
      flatEntry ? '../h5_site' : `../h5_site/${slug}`,
    ),
    emptyOutDir: true,
    assetsInlineLimit: 100000000,
    cssCodeSplit: false,
  },
})

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const entry = process.env.H5_SITE_ENTRY || 'tslow_entry.htm'
const slug = process.env.H5_APP_SLUG || 'tintoo'
const flat = !entry.includes('/') && !/^index\.html?$/i.test(entry)
const outDir = path.resolve(__dirname, flat ? '../../h5_site' : `../../h5_site/${slug}`)
const src = path.join(outDir, 'index.html')
const dest = path.join(outDir, entry)

if (!fs.existsSync(src)) {
  console.error(`rename-entry: missing ${src}`)
  process.exit(1)
}

if (path.resolve(src) !== path.resolve(dest)) {
  fs.renameSync(src, dest)
  console.log(`rename-entry: ${path.basename(src)} → ${path.basename(dest)}`)
} else {
  console.log('rename-entry: entry already index.html')
}

