/// <reference types="vite/client" />

declare module '*.vue' {
  import type { DefineComponent } from 'vue'
  const component: DefineComponent<object, object, unknown>
  export default component
}

interface TintooBridgeEnvelope {
  id?: string
  data?: unknown
  result?: unknown
  error?: { code?: string; message?: string }
}

interface Window {
  tintooBridge?: {
    postMessage: (msg: { id: string; action: string; payload?: unknown }) => void
  }
  webkit?: {
    messageHandlers?: {
      tintooBridge?: { postMessage: (msg: unknown) => void }
    }
  }
  tintooBridgeCallback?: (id: string, envelope: TintooBridgeEnvelope) => void
}

type Pending = {
  resolve: (value: unknown) => void
  reject: (reason?: unknown) => void
}

const pending = new Map<string, Pending>()
let seq = 0

function isNative(): boolean {
  return Boolean(
    window.tintooBridge?.postMessage ||
      window.webkit?.messageHandlers?.tintooBridge?.postMessage,
  )
}

function post(msg: { id: string; action: string; payload?: unknown }) {
  if (window.tintooBridge?.postMessage) {
    window.tintooBridge.postMessage(msg)
    return
  }
  const handler = window.webkit?.messageHandlers?.tintooBridge
  if (handler?.postMessage) {
    handler.postMessage(msg)
    return
  }
  throw new Error('NATIVE_BRIDGE_UNAVAILABLE')
}

window.tintooBridgeCallback = (id, envelope) => {
  const slot = pending.get(id)
  if (!slot) return
  pending.delete(id)
  if (envelope?.error) {
    const err = new Error(envelope.error.message || 'Native lane error') as Error & {
      code?: string
    }
    err.code = envelope.error.code || 'UNKNOWN'
    slot.reject(err)
    return
  }
  const data =
    envelope?.data !== undefined
      ? envelope.data
      : envelope?.result !== undefined
        ? envelope.result
        : envelope
  slot.resolve(data)
}

export function bridgeCall<T = unknown>(
  action: string,
  payload: Record<string, unknown> = {},
): Promise<T> {
  return new Promise((resolve, reject) => {
    const id = `cb_${++seq}_${Date.now()}`
    pending.set(id, {
      resolve: (v) => resolve(v as T),
      reject,
    })
    try {
      if (!isNative()) {
        pending.delete(id)
        resolve(stubReply(action, payload) as T)
        return
      }
      post({ id, action, payload })
    } catch (err) {
      pending.delete(id)
      reject(err)
    }
  })
}

function stubReply(action: string, payload: Record<string, unknown>): unknown {
  switch (action) {
    case 'shellReady':
      return { ready: true }
    case 'getDeviceInfo':
      return {
        appVersion: '1.0.0',
        language: 'en',
        safeAreaTop: 47,
        safeAreaBottom: 34,
        safeAreaLeft: 0,
        safeAreaRight: 0,
      }
    case 'pickImage':
      return { path: `care/stub_${Date.now()}.jpg` }
    case 'mediaServe':
      return { url: '' }
    case 'saveImageToAlbum':
      return { saved: true }
    case 'purchase':
      return {
        productId: payload.productId || 'Tints00',
        coinsAdded: 99,
        balance: 99,
        transactionId: `stub_${Date.now()}`,
      }
    case 'getProducts':
      return []
    case 'openExternalUrl':
      if (typeof payload.url === 'string') window.open(payload.url, '_blank')
      return { opened: true }
    case 'writeFile':
      return { path: payload.path || 'exports/period_card.png' }
    case 'readFile':
      return { path: payload.path, base64: '', byteLength: 0 }
    case 'getPermissionStatus':
    case 'requestPermission':
      return { status: 'granted' }
    case 'reload':
      return { reloaded: true }
    case 'goBack':
      return { wentBack: false }
    default:
      return {}
  }
}

export function mediaUrlFor(path: string): string {
  if (!path) return ''
  if (path.startsWith('http') || path.startsWith('blob:') || path.startsWith('data:')) {
    return path
  }
  return `tintoo-asset://local/${path.replace(/^\//, '')}`
}

export async function resolveMediaUrl(path: string): Promise<string> {
  if (!path) return ''
  try {
    const res = await bridgeCall<{ url?: string; base64?: string }>('readFile', { path })
    if (res?.base64) return `data:image/jpeg;base64,${res.base64}`
  } catch {
    /* fall through */
  }
  try {
    const res = await bridgeCall<{ url?: string }>('mediaServe', { path })
    if (res?.url) return res.url
  } catch {
    /* fall through */
  }
  return mediaUrlFor(path)
}

export { isNative }

export function loadJson<T>(key: string, fallback: T): T {
  try {
    const raw = localStorage.getItem(key)
    if (!raw) return fallback
    return JSON.parse(raw) as T
  } catch {
    return fallback
  }
}

export function saveJson(key: string, value: unknown) {
  localStorage.setItem(key, JSON.stringify(value))
}

export function uid(prefix: string): string {
  return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`
}

const LOCALE = 'en-US'

export function formatDateLabel(isoOrKey: string): string {
  const d = new Date(isoOrKey.includes('T') ? isoOrKey : `${isoOrKey}T12:00:00`)
  if (Number.isNaN(d.getTime())) return isoOrKey
  return new Intl.DateTimeFormat(LOCALE, {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
  }).format(d)
}

export function formatShortDay(isoOrKey: string): string {
  const d = new Date(isoOrKey.includes('T') ? isoOrKey : `${isoOrKey}T12:00:00`)
  if (Number.isNaN(d.getTime())) return isoOrKey
  return new Intl.DateTimeFormat(LOCALE, { month: 'short', day: 'numeric' }).format(d)
}

export function dayKeyFromDate(d = new Date()): string {
  const y = d.getFullYear()
  const m = String(d.getMonth() + 1).padStart(2, '0')
  const day = String(d.getDate()).padStart(2, '0')
  return `${y}-${m}-${day}`
}

export function contextualGreeting(now = new Date()): string {
  const hour = now.getHours()
  if (hour < 11) return 'Morning gloss rinse check'
  if (hour < 17) return 'Midday color-care window'
  if (hour < 21) return 'Evening mask & gloss hour'
  return 'Late gloss-cycle scan'
}

export function contextualSubline(dueToday: number, planCount: number): string {
  if (planCount <= 0) {
    return 'Spin the care ring after you add the first water-match plan.'
  }
  if (dueToday <= 0) return 'Your tint ring is clear today — peek ahead for mask days.'
  if (dueToday === 1) return 'One care step is due today — tap the glowing node.'
  return `${dueToday} care steps due today · spin the ring to pick a day.`
}

export type LegalSection = {
  heading: string
  paragraphs: string[]
}

export type FormattedLegal = {
  title: string
  meta: string
  sections: LegalSection[]
  bodyHtml: string
}

export function formatLegalBody(raw: string, prefix = 'tslow'): FormattedLegal {
  const text = (raw || '').replace(/\r\n/g, '\n').trim()
  const lines = text.split('\n')
  let title = 'Agreement'
  let meta = ''
  const sections: LegalSection[] = []
  let current: LegalSection | null = null
  let sawFirstSubstantive = false

  const pushPara = (line: string) => {
    const cleaned = line.trim()
    if (!cleaned) return
    if (!current) {
      current = { heading: 'Overview', paragraphs: [] }
      sections.push(current)
    }
    current.paragraphs.push(cleaned)
  }

  const isSectionHeader = (line: string) => {
    const t = line.trim()
    if (!t || t.length > 72) return false
    if (/[.!?,;:]$/.test(t)) return false
    if (t.includes('  ')) return false
    const words = t.split(/\s+/)
    if (words.length > 10) return false
    return (
      /^(Latest Updated|No Personal|Device Identifier|Local |Photos and|Purchases|Analytics|Content Safety|Your Rights|Children|Changes|Contact|Service Overview|Device Access|License|Virtual Currency|User Obligations|Prohibited|Intellectual|Disclaimer|Termination|Governing|Limitation|Information We|Technical |Administrative )/i.test(
        t,
      ) || /^[A-Z][A-Za-z0-9'’&\-]*(?:\s+[A-Z][A-Za-z0-9'’&\-]*){0,8}$/.test(t)
    )
  }

  for (const line of lines) {
    const heading = /^(#{1,3})\s+(.*)$/.exec(line)
    if (heading) {
      const level = heading[1].length
      const label = heading[2].trim()
      if (level === 1 && title === 'Agreement') {
        title = label
        continue
      }
      current = { heading: label, paragraphs: [] }
      sections.push(current)
      continue
    }
    if (/^Latest Updated:/i.test(line.trim()) && !meta) {
      meta = line.trim()
      continue
    }
    if (!sawFirstSubstantive && /Agreement|Policy/i.test(line.trim()) && line.trim().split(/\s+/).length <= 6) {
      title = line.trim()
      sawFirstSubstantive = true
      continue
    }
    if (isSectionHeader(line)) {
      sawFirstSubstantive = true
      current = { heading: line.trim(), paragraphs: [] }
      sections.push(current)
      continue
    }
    if (line.trim()) sawFirstSubstantive = true
    pushPara(line)
  }

  if (!sections.length) {
    sections.push({
      heading: 'Overview',
      paragraphs: text ? [text] : ['Document unavailable.'],
    })
  }

  const bodyHtml = sections
    .map((sec) => {
      const paras = sec.paragraphs
        .map((p) => `<p class="c-${prefix}-legal-para">${escapeHtml(p)}</p>`)
        .join('')
      return `<section class="c-${prefix}-legal-section"><h3>${escapeHtml(sec.heading)}</h3>${paras}</section>`
    })
    .join('')

  return { title, meta, sections, bodyHtml }
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
}

import { reactive, computed } from 'vue'
import { loadJson, saveJson, uid } from '@/lib/storage'
import { EXPORT_COIN_COST, INITIAL_FREE_EXPORTS } from '@/lib/iapCatalog'
import { dayKeyFromDate } from '@/lib/uiLocale'

export type CareKind = 'rinse' | 'mask' | 'gloss' | 'check'
export type CareStatus = 'due' | 'done' | 'skipped'
export type PhBand = 'acid' | 'neutral' | 'alkaline'

export type WaterMatchPlan = {
  id: string
  planLabel: string
  waterHardnessPpm: number
  phBand: PhBand
  rinseRecipe: string
  maskCadenceDays: number
  glossCadenceDays: number
  createdAt: string
}

export type RingDayNode = {
  dayKey: string
  dueCount: number
  doneCount: number
  urgencyScore: number
  orbitIndex: number
}

export type TintCareEntry = {
  id: string
  planId: string
  dayKey: string
  title: string
  careKind: CareKind
  status: CareStatus
  dueAt: string
  note: string
  photoPath: string
  updatedAt: string
}

export type PlanBreakdown = {
  planId: string
  planLabel: string
  dueCount: number
  doneCount: number
}

export type PeriodExportSnapshot = {
  id: string
  rangeStart: string
  rangeEnd: string
  dueTotal: number
  doneTotal: number
  planBreakdown: PlanBreakdown[]
  cardLayoutRev: number
  exportedAt: string
}

export type WalletState = {
  coinBalance: number
  freeExportsRemaining: number
}

const KEYS = {
  plans: 'tintoo_plans_v1',
  ring: 'tintoo_ring_v1',
  entries: 'tintoo_entries_v1',
  exports: 'tintoo_exports_v1',
  wallet: 'tintoo_wallet_v1',
  welcome: 'welcome_done_v1',
}

const CARE_KINDS: CareKind[] = ['rinse', 'mask', 'gloss', 'check']

const loadedWallet = loadJson<WalletState>(KEYS.wallet, {
  coinBalance: 0,
  freeExportsRemaining: INITIAL_FREE_EXPORTS,
})

const state = reactive({
  plans: loadJson<WaterMatchPlan[]>(KEYS.plans, []),
  ring: loadJson<RingDayNode[]>(KEYS.ring, []),
  entries: loadJson<TintCareEntry[]>(KEYS.entries, []),
  exports: loadJson<PeriodExportSnapshot[]>(KEYS.exports, []),
  wallet: {
    coinBalance: loadedWallet.coinBalance ?? 0,
    freeExportsRemaining:
      typeof loadedWallet.freeExportsRemaining === 'number'
        ? loadedWallet.freeExportsRemaining
        : INITIAL_FREE_EXPORTS,
  } as WalletState,
  welcomeDone: localStorage.getItem(KEYS.welcome) === 'true',
  snackbar: '' as string,
  snackbarTimer: 0 as number,
  selectedDayKey: dayKeyFromDate(),
  exportRangeStart: dayKeyFromDate(new Date(Date.now() - 6 * 86400000)),
  exportRangeEnd: dayKeyFromDate(),
})

function persistAll() {
  saveJson(KEYS.plans, state.plans)
  saveJson(KEYS.ring, state.ring)
  saveJson(KEYS.entries, state.entries)
  saveJson(KEYS.exports, state.exports)
  saveJson(KEYS.wallet, state.wallet)
}

export function showToast(message: string) {
  state.snackbar = message
  window.clearTimeout(state.snackbarTimer)
  state.snackbarTimer = window.setTimeout(() => {
    state.snackbar = ''
  }, 2600)
}

export function markWelcomeDone() {
  state.welcomeDone = true
  localStorage.setItem(KEYS.welcome, 'true')
}

function overdueBonus(entry: TintCareEntry, now: number): number {
  if (entry.status !== 'due') return 0
  const due = new Date(entry.dueAt).getTime()
  if (Number.isNaN(due) || due >= now) return 0
  return 2
}

export function recomputeRing() {
  const now = Date.now()
  const byDay = new Map<string, { due: number; done: number; urgency: number }>()
  for (const entry of state.entries) {
    if (entry.status === 'skipped') continue
    const slot = byDay.get(entry.dayKey) || { due: 0, done: 0, urgency: 0 }
    if (entry.status === 'due') {
      slot.due += 1
      slot.urgency += 3 + overdueBonus(entry, now)
    } else if (entry.status === 'done') {
      slot.done += 1
    }
    byDay.set(entry.dayKey, slot)
  }
  const keys = [...byDay.keys()].sort()
  state.ring = keys.map((dayKey, orbitIndex) => {
    const slot = byDay.get(dayKey)!
    return {
      dayKey,
      dueCount: slot.due,
      doneCount: slot.done,
      urgencyScore: slot.urgency,
      orbitIndex,
    }
  })
  persistAll()
}

recomputeRing()

export function setSelectedDay(dayKey: string) {
  state.selectedDayKey = dayKey
}

export function createPlan(input: {
  planLabel: string
  waterHardnessPpm: number
  phBand: PhBand
  rinseRecipe: string
  maskCadenceDays: number
  glossCadenceDays: number
}): { ok: true; plan: WaterMatchPlan } | { ok: false; error: string } {
  const planLabel = input.planLabel.trim()
  if (planLabel.length < 1 || planLabel.length > 32) {
    return { ok: false, error: 'Plan label must be 1–32 characters.' }
  }
  const dup = state.plans.some(
    (p) => p.planLabel.trim().toLowerCase() === planLabel.toLowerCase(),
  )
  if (dup) return { ok: false, error: 'That plan label is already in use.' }
  if (
    !Number.isFinite(input.waterHardnessPpm) ||
    input.waterHardnessPpm < 0 ||
    input.waterHardnessPpm > 500
  ) {
    return { ok: false, error: 'Hardness 0–500 ppm; cadence 1–30 days.' }
  }
  if (
    input.maskCadenceDays < 1 ||
    input.maskCadenceDays > 30 ||
    input.glossCadenceDays < 1 ||
    input.glossCadenceDays > 30
  ) {
    return { ok: false, error: 'Hardness 0–500 ppm; cadence 1–30 days.' }
  }
  const plan: WaterMatchPlan = {
    id: uid('plan'),
    planLabel,
    waterHardnessPpm: Math.round(input.waterHardnessPpm),
    phBand: input.phBand,
    rinseRecipe: input.rinseRecipe.trim() || 'Cool rinse finish',
    maskCadenceDays: Math.round(input.maskCadenceDays),
    glossCadenceDays: Math.round(input.glossCadenceDays),
    createdAt: new Date().toISOString(),
  }
  state.plans.unshift(plan)
  persistAll()
  return { ok: true, plan }
}

export function createEntry(input: {
  planId: string
  dayKey: string
  title: string
  careKind: CareKind
  note?: string
  photoPath?: string
  dueAt?: string
}): { ok: true; entry: TintCareEntry } | { ok: false; error: string } {
  if (!state.plans.length) {
    return { ok: false, error: 'Create a water-match plan first.' }
  }
  const plan = state.plans.find((p) => p.id === input.planId)
  if (!plan) return { ok: false, error: 'Linked plan is missing.' }
  const title = input.title.trim()
  if (title.length < 1 || title.length > 48) {
    return { ok: false, error: 'Title must be 1–48 characters.' }
  }
  if (!CARE_KINDS.includes(input.careKind)) {
    return { ok: false, error: 'Pick rinse, mask, gloss, or check.' }
  }
  const now = new Date().toISOString()
  const entry: TintCareEntry = {
    id: uid('care'),
    planId: plan.id,
    dayKey: input.dayKey,
    title,
    careKind: input.careKind,
    status: 'due',
    dueAt: input.dueAt || `${input.dayKey}T18:00:00`,
    note: (input.note || '').trim(),
    photoPath: input.photoPath || '',
    updatedAt: now,
  }
  state.entries.unshift(entry)
  recomputeRing()
  return { ok: true, entry }
}

export function updateEntry(
  id: string,
  patch: Partial<Pick<TintCareEntry, 'title' | 'careKind' | 'planId' | 'dueAt' | 'note' | 'status' | 'photoPath'>>,
): { ok: true } | { ok: false; error: string } {
  const entry = state.entries.find((e) => e.id === id)
  if (!entry) return { ok: false, error: 'Care step not found.' }
  if (patch.title !== undefined) {
    const title = patch.title.trim()
    if (title.length < 1 || title.length > 48) {
      return { ok: false, error: 'Title must be 1–48 characters.' }
    }
    entry.title = title
  }
  if (patch.careKind !== undefined) {
    if (!CARE_KINDS.includes(patch.careKind)) {
      return { ok: false, error: 'Pick rinse, mask, gloss, or check.' }
    }
    entry.careKind = patch.careKind
  }
  if (patch.planId !== undefined) {
    if (!state.plans.some((p) => p.id === patch.planId)) {
      return { ok: false, error: 'Linked plan is missing.' }
    }
    entry.planId = patch.planId
  }
  if (patch.dueAt !== undefined) entry.dueAt = patch.dueAt
  if (patch.note !== undefined) entry.note = patch.note.trim()
  if (patch.status !== undefined) entry.status = patch.status
  if (patch.photoPath !== undefined) entry.photoPath = patch.photoPath
  entry.updatedAt = new Date().toISOString()
  recomputeRing()
  return { ok: true }
}

export function softArchiveEntry(id: string) {
  return updateEntry(id, { status: 'skipped' })
}

export function markEntryDone(id: string) {
  return updateEntry(id, { status: 'done' })
}

export function hardPurgeEntry(id: string) {
  state.entries = state.entries.filter((e) => e.id !== id)
  recomputeRing()
}

function sortAgenda(list: TintCareEntry[]): TintCareEntry[] {
  const rank = (s: CareStatus) => (s === 'due' ? 0 : s === 'done' ? 1 : 2)
  return [...list].sort((a, b) => {
    const r = rank(a.status) - rank(b.status)
    if (r !== 0) return r
    const t = new Date(a.dueAt).getTime() - new Date(b.dueAt).getTime()
    if (t !== 0) return t
    return a.title.localeCompare(b.title)
  })
}

const plans = computed(() => state.plans)
const ringNodes = computed(() => state.ring)
const selectedDayEntries = computed(() =>
  sortAgenda(state.entries.filter((e) => e.dayKey === state.selectedDayKey)),
)
const agendaAll = computed(() => sortAgenda(state.entries.filter((e) => e.status !== 'skipped')))
const dueTodayCount = computed(
  () =>
    state.entries.filter((e) => e.dayKey === dayKeyFromDate() && e.status === 'due').length,
)

export function entriesForDay(dayKey: string) {
  return sortAgenda(state.entries.filter((e) => e.dayKey === dayKey))
}

export function entriesForPlan(planId: string) {
  return sortAgenda(state.entries.filter((e) => e.planId === planId && e.status === 'due'))
}

export function periodStats(rangeStart: string, rangeEnd: string) {
  const inRange = state.entries.filter(
    (e) => e.dayKey >= rangeStart && e.dayKey <= rangeEnd && e.status !== 'skipped',
  )
  const dueTotal = inRange.filter((e) => e.status === 'due').length
  const doneTotal = inRange.filter((e) => e.status === 'done').length
  const planBreakdown: PlanBreakdown[] = state.plans.map((plan) => {
    const rows = inRange.filter((e) => e.planId === plan.id)
    return {
      planId: plan.id,
      planLabel: plan.planLabel,
      dueCount: rows.filter((e) => e.status === 'due').length,
      doneCount: rows.filter((e) => e.status === 'done').length,
    }
  }).filter((p) => p.dueCount + p.doneCount > 0)
  return { dueTotal, doneTotal, planBreakdown, inRange }
}

export function canExportNow(): { ok: true } | { ok: false; error: string } {
  if (state.wallet.freeExportsRemaining > 0) return { ok: true }
  if (state.wallet.coinBalance >= EXPORT_COIN_COST) return { ok: true }
  return { ok: false, error: 'Need 30 coins or a free export slot.' }
}

export function consumeExportQuota(): { ok: true; mode: 'free' | 'coins' } | { ok: false; error: string } {
  if (state.wallet.freeExportsRemaining > 0) {
    state.wallet.freeExportsRemaining -= 1
    persistAll()
    return { ok: true, mode: 'free' }
  }
  if (state.wallet.coinBalance < EXPORT_COIN_COST) {
    return { ok: false, error: 'Need 30 coins or a free export slot.' }
  }
  state.wallet.coinBalance -= EXPORT_COIN_COST
  persistAll()
  return { ok: true, mode: 'coins' }
}

export function addCoins(n: number) {
  state.wallet.coinBalance += Math.max(0, Math.round(n))
  persistAll()
}

export function saveExportSnapshot(rangeStart: string, rangeEnd: string) {
  const stats = periodStats(rangeStart, rangeEnd)
  const snap: PeriodExportSnapshot = {
    id: uid('exp'),
    rangeStart,
    rangeEnd,
    dueTotal: stats.dueTotal,
    doneTotal: stats.doneTotal,
    planBreakdown: stats.planBreakdown,
    cardLayoutRev: 1,
    exportedAt: new Date().toISOString(),
  }
  state.exports.unshift(snap)
  persistAll()
  return snap
}

/** Build 14 orbit day keys centered on today for empty-ring preview */
export function orbitPreviewDays(count = 14): string[] {
  const today = new Date()
  const keys: string[] = []
  for (let i = -3; i < count - 3; i += 1) {
    const d = new Date(today)
    d.setDate(today.getDate() + i)
    keys.push(dayKeyFromDate(d))
  }
  return keys
}

export function nodeForDay(dayKey: string): RingDayNode | undefined {
  return state.ring.find((n) => n.dayKey === dayKey)
}

