export const TAB_ROUTES = ['/ring', '/plans', '/agenda', '/settings'] as const
export const OVERLAY_PATHS = ['/legal', '/capture'] as const

export function isOverlayPath(path: string): boolean {
  const clean = path.split('?')[0]
  return (OVERLAY_PATHS as readonly string[]).includes(clean)
}

export function isTabRoute(path: string): boolean {
  const clean = path.split('?')[0]
  return (TAB_ROUTES as readonly string[]).includes(clean)
