let overlayBase: { path: string; query: Record<string, string> } | null = null

export function getOverlayBase() {
  return overlayBase
}

export function setOverlayBase(route: RouteLocationNormalized) {
  if (isOverlayPath(route.path)) return
  overlayBase = {
    path: route.path,
    query: Object.fromEntries(
      Object.entries(route.query).map(([k, v]) => [k, String(v ?? '')]),
    ),
  }
}

export const overlayFallbackBase = { path: '/ring', query: {} as Record<string, string> }

const router = createRouter({
  history: createWebHashHistory(),
  routes,
})

router.beforeEach((to, from) => {
  if (isOverlayPath(to.path)) {
    if (!isOverlayPath(from.path) && from.path && from.path !== '/') {
      setOverlayBase(from)
    } else if (!overlayBase) {
      overlayBase = { ...overlayFallbackBase }
    }
  }

  if (to.path === '/splash' || to.path === '/welcome' || to.path === '/legal') return true
  if (!domainState.welcomeDone && to.path !== '/welcome') {
    return { path: '/welcome' }
  }
  return true
})

router.afterEach((to) => {
  const scene = String(to.meta.scene || 'calm-wash')
  document.documentElement.setAttribute('data-tslow-scene', scene)
})

export default router

