  min-height: 100vh;
  isolation: isolate;
}

/* Ambient canvas — Reminder Ring Orbit */
.u-tslow-ambient {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.u-tslow-ambient__base {
  position: absolute;
  inset: 0;
  background: var(--tslow-background);
}

.u-tslow-ambient__mesh {
  position: absolute;
  inset: -20%;
  background:
    radial-gradient(circle at 22% 18%, var(--tslow-ambient-a), transparent 42%),
    radial-gradient(circle at 78% 28%, var(--tslow-ambient-b), transparent 46%),
    radial-gradient(circle at 55% 82%, var(--tslow-ambient-c), transparent 48%);
  filter: blur(8px);
  animation: tslow-orbit-drift 24s linear infinite;
}

.u-tslow-ambient__grid {
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(var(--tslow-ambient-grid) 1.2px, transparent 1.2px);
  background-size: 22px 22px;
  opacity: 0.7;
  mask-image: radial-gradient(circle at 50% 35%, #000 35%, transparent 78%);
}

.u-tslow-ambient__rings {
  position: absolute;
  left: 50%;
  top: 18%;
  width: min(92vw, 380px);
  height: min(92vw, 380px);
  transform: translateX(-50%);
  opacity: 0.55;
  animation: tslow-orbit-drift 24s linear infinite;
}

[data-tslow-scene='gate-orbit'] .u-tslow-ambient__rings,
[data-tslow-scene='hub-rings'] .u-tslow-ambient__rings,
[data-tslow-scene='boot-wash'] .u-tslow-ambient__rings,
[data-tslow-scene='detail-ring'] .u-tslow-ambient__rings {
  opacity: 0.85;
}

[data-tslow-scene='list-rings'] .u-tslow-ambient__rings {
  opacity: 0.45;
}

[data-tslow-scene='calm-wash'] .u-tslow-ambient__rings,
[data-tslow-scene='form-focus'] .u-tslow-ambient__rings {
  opacity: 0.22;
  animation: none;
}

@keyframes tslow-orbit-drift {
  from { transform: translateX(-50%) rotate(0deg); }
  to { transform: translateX(-50%) rotate(360deg); }
}

@keyframes tslow-due-pulse {
  0%, 100% { opacity: 0.55; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.05); }
}

@keyframes tslow-spin-soft {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes tslow-fade-up {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes tslow-shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

.tslow-fade-up {
  animation: tslow-fade-up 0.4s cubic-bezier(0.34, 1.4, 0.64, 1) both;
}

.tslow-ring-spin {
  animation: tslow-spin-soft 18s linear infinite;
}

.tslow-due-pulse {
  animation: tslow-due-pulse 3s ease-in-out infinite;
}

.tslow-shimmer {
  background: linear-gradient(
    90deg,
    rgba(8,145,178,0.08) 0%,
    rgba(5,150,105,0.16) 45%,
    rgba(8,145,178,0.08) 100%
  );
  background-size: 200% 100%;
  animation: tslow-shimmer 2.4s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  .u-tslow-ambient__mesh,
  .u-tslow-ambient__rings,
  .tslow-ring-spin,
  .tslow-fade-up,
  .tslow-due-pulse,
  .tslow-shimmer,
  .c-tslow-welcome-hero__glow,
  .c-tslow-ring-hero__glow,
  .c-tslow-day-node--due {
    animation: none !important;
  }
}

/* LAYOUT:pipeline — auto-synced; do not hand-edit */
:root {
  --safe-top: env(safe-area-inset-top, constant(safe-area-inset-top, 0px));
  --safe-bottom: env(safe-area-inset-bottom, constant(safe-area-inset-bottom, 0px));
  --tslow-appbar-height: 48px;
  --tslow-tabbar-height: 56px;
  --tslow-page-inset-top: calc(var(--tslow-appbar-height) + var(--safe-top));
  --tslow-page-inset-bottom: calc(var(--tslow-tabbar-height) + var(--safe-bottom));
  --tslow-page-content-gap: 12px;
}

.c-tslow-appbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 40;
  display: grid;
  grid-template-columns: 44px 1fr 44px;
  align-items: end;
  height: var(--tslow-page-inset-top);
  padding: var(--safe-top) 8px 0;
  box-sizing: border-box;
  background: color-mix(in srgb, var(--tslow-sheet) 92%, transparent);
  border-bottom: 2px solid #083344;
}

.c-tslow-appbar__title {
  grid-column: 2;
  text-align: center;
  font-size: 16px;
  font-weight: 700;
  line-height: var(--tslow-appbar-height);
  max-height: var(--tslow-appbar-height);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.c-tslow-appbar__back {
  grid-column: 1;
  justify-self: start;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  margin-bottom: 4px;
  padding: 0;
  border: 2px solid #083344;
  border-radius: 8px;
  background: var(--tslow-muted);
  color: var(--tslow-primary);
  box-shadow: 2px 2px 0 rgba(8, 51, 68, 0.2);
  cursor: pointer;
}

.c-tslow-appbar__back:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}

.c-tslow-appbar__spacer {
  grid-column: 3;
}

.c-tslow-tabbar {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 40;
  display: flex;
  justify-content: space-around;
  align-items: center;
  height: var(--tslow-page-inset-bottom);
  padding: 0 0 var(--safe-bottom);
  box-sizing: border-box;
  background: color-mix(in srgb, var(--tslow-sheet) 94%, transparent);
  border-top: 2px solid #083344;
}

.c-tslow-tabbar__item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  min-width: 64px;
  min-height: 44px;
  color: var(--tslow-on-muted);
  text-decoration: none;
  font-size: 11px;
  font-weight: 600;
  background: none;
  border: none;
  cursor: pointer;
}

.c-tslow-tabbar__item--active {
  color: var(--tslow-primary);
}

.page-shell {
  min-height: 100%;
  overflow-x: hidden;
  max-width: 100%;
  padding: calc(var(--tslow-page-inset-top) + var(--tslow-page-content-gap)) 16px var(--tslow-page-inset-bottom);
  box-sizing: border-box;
}

.page-full {
  position: relative;
  z-index: 1;
  min-height: 100vh;
  padding: calc(16px + var(--safe-top)) 16px calc(16px + var(--safe-bottom));
  box-sizing: border-box;
  color: var(--tslow-foreground);
}

[data-tslow-scene='boot-wash'] .page-full,
[data-tslow-scene='gate-orbit'] .page-full {
  color: var(--tslow-on-ambient);
}

.page-stack {
  min-height: 100vh;
  padding: calc(var(--tslow-page-inset-top) + var(--tslow-page-content-gap)) 16px calc(16px + var(--safe-bottom));
  box-sizing: border-box;
}
